insert into proyectos (usuario_id, titulo, area, descripcion, impacto, presupuesto) values
('11111111-1111-1111-1111-111111111111','Biofertilizante a partir de residuos de cacao','Agroindustria','Desarrollo de un biofertilizante líquido elaborado con la cáscara y mucílago del cacao, que mejora la fertilidad del suelo y reduce el uso de fertilizantes químicos en parcelas pequeñas.','Reduce costos a productores de cacao en Tabasco y aprovecha un residuo que hoy se desecha.',180000),
('11111111-1111-1111-1111-111111111111','Sensor IoT de humedad de suelo de bajo costo','Electrónica','Sensor inalámbrico con microcontrolador ESP32 que mide humedad y temperatura del suelo y envía los datos a una aplicación móvil para optimizar el riego.','Ahorro de agua de hasta 30 % en cultivos y acceso a tecnología de agricultura de precisión para pequeños productores.',95000),
('11111111-1111-1111-1111-111111111111','Plataforma de diagnóstico temprano de diabetes con IA','Salud','Modelo de aprendizaje automático que estima el riesgo de diabetes tipo 2 a partir de cuestionarios y análisis clínicos básicos, pensado para clínicas rurales sin especialista.','Detección oportuna en comunidades con poco acceso a servicios médicos.',320000),
('11111111-1111-1111-1111-111111111111','Paneles solares flexibles para techos de lámina','Energía','Prototipo de módulo fotovoltaico ligero y flexible que se instala sobre techos de lámina sin estructura adicional, para viviendas de bajos ingresos.','Reduce el recibo de electricidad y facilita la energía limpia en zonas cálidas y húmedas.',410000),
('11111111-1111-1111-1111-111111111111','Aplicación de gestión de inventarios para tianguis','Software','Aplicación móvil sencilla con reconocimiento de voz para que comerciantes de mercados registren inventario y ventas sin conocimientos técnicos.','Digitaliza a pequeños comerciantes y mejora su control financiero.',70000),
('11111111-1111-1111-1111-111111111111','Bioplástico a base de almidón de plátano','Materiales','Material biodegradable fabricado con almidón de plátano macho de desecho, alternativa a empaques plásticos de un solo uso.','Reduce la contaminación por plásticos y crea valor para la cadena platanera.',150000),
('11111111-1111-1111-1111-111111111111','Monitoreo de calidad del agua con drones y visión artificial','Medio ambiente','Sistema que usa drones y modelos de visión por computadora para detectar floración de algas y contaminación en ríos y lagunas.','Alerta temprana para autoridades ambientales y comunidades pesqueras.',380000),
('11111111-1111-1111-1111-111111111111','Detección de mastitis en ganado mediante análisis de leche','Biotecnología','Kit rápido de biosensores para detectar mastitis subclínica en vacas lecheras directamente en el establo.','Mejora la producción lechera y disminuye pérdidas económicas de ganaderos.',210000),
('11111111-1111-1111-1111-111111111111','Prótesis de mano impresas en 3D con control mioeléctrico','Salud','Prótesis funcionales de bajo costo fabricadas por impresión 3D y controladas con sensores musculares, para personas con amputación.','Acceso a prótesis a una fracción del precio comercial.',260000),
('11111111-1111-1111-1111-111111111111','Asistente virtual para orientación vocacional con IA','Software','Chatbot basado en modelos de lenguaje que orienta a estudiantes de bachillerato sobre carreras y oportunidades laborales según sus intereses y habilidades.','Reduce la deserción universitaria y mejora la elección de carrera.',85000);
insert into campanas (usuario_id, titulo, area, descripcion, requisitos, monto, fecha_cierre) values
('22222222-2222-2222-2222-222222222222','Reto: Agricultura inteligente para pequeños productores','Agroindustria','Buscamos soluciones tecnológicas que ayuden a productores agrícolas a ahorrar agua, reducir fertilizantes y monitorear sus cultivos con sensores y datos.','Prototipo funcional o prueba de concepto; impacto medible en costos; escalable a bajo costo.',500000,'2027-03-31'),
('22222222-2222-2222-2222-222222222222','Convocatoria: Salud digital en comunidades rurales','Salud','Financiamos proyectos que usen inteligencia artificial o dispositivos de bajo costo para mejorar el diagnóstico y la atención médica en zonas con poco acceso a especialistas.','Validación con profesionales de salud; protección de datos del paciente; plan de implementación.',700000,'2027-04-15'),
('22222222-2222-2222-2222-222222222222','Fondo de transición energética y economía circular','Energía','Apoyo a proyectos de energía renovable, eficiencia energética y materiales sustentables que reduzcan emisiones y residuos en el sector productivo.','Estudio de viabilidad técnica; reducción de emisiones cuantificada; equipo multidisciplinario.',900000,'2027-05-20'),
('22222222-2222-2222-2222-222222222222','Reto: Herramientas digitales para micronegocios','Software','Buscamos aplicaciones y plataformas sencillas que ayuden a micronegocios y comerciantes a digitalizar ventas, inventarios y finanzas.','Interfaz en español, usable en celular básico; modelo de adopción para usuarios no técnicos.',300000,'2027-02-28'),
('22222222-2222-2222-2222-222222222222','Convocatoria: Monitoreo y protección del medio ambiente','Medio ambiente','Financiamiento para tecnologías de monitoreo de agua, aire y suelo mediante sensores, drones o inteligencia artificial que apoyen a autoridades y comunidades.','Datos abiertos; piloto en campo; colaboración con una comunidad local.',600000,'2027-06-10');
